ALTER POLICY crew_receipts_read ON storage.objects USING (bucket_id='crew-receipts' AND EXISTS (SELECT 1 FROM public.project_participants p JOIN public.organizations o ON o.id=p.organization_id WHERE p.organization_id::text=(storage.foldername(storage.objects.name))[1] AND p.project_id::text=(storage.foldername(storage.objects.name))[2] AND p.invite_status='ACCEPTED' AND o.type='FC' AND public.user_in_org(auth.uid(),p.organization_id) AND public.can_see_project(p.project_id)));
ALTER POLICY crew_receipts_insert ON storage.objects WITH CHECK (bucket_id='crew-receipts' AND EXISTS (SELECT 1 FROM public.project_participants p JOIN public.organizations o ON o.id=p.organization_id WHERE p.organization_id::text=(storage.foldername(storage.objects.name))[1] AND p.project_id::text=(storage.foldername(storage.objects.name))[2] AND p.invite_status='ACCEPTED' AND o.type='FC' AND public.user_in_org(auth.uid(),p.organization_id) AND public.can_see_project(p.project_id)));
ALTER POLICY crew_receipts_delete ON storage.objects USING (bucket_id='crew-receipts' AND EXISTS (SELECT 1 FROM public.project_participants p JOIN public.organizations o ON o.id=p.organization_id WHERE p.organization_id::text=(storage.foldername(storage.objects.name))[1] AND p.project_id::text=(storage.foldername(storage.objects.name))[2] AND p.invite_status='ACCEPTED' AND o.type='FC' AND public.user_in_org(auth.uid(),p.organization_id) AND public.can_see_project(p.project_id)));